BEGIN TRANSACTION;
CREATE TABLE "data_source" (
	"id"	INTEGER,
	"name"	TEXT NOT NULL,
	"type"	TEXT,
	"storage_table"	TEXT,
	"src_link"	TEXT,
	"web_path"	TEXT,
	"api_path"	TEXT,
	"api_method"	TEXT,
	"api_params"	TEXT,
	"api_res_sample"	TEXT,
	"memo"	TEXT,
	"updated_at"	DATETIME DEFAULT CURRENT_TIMESTAMP, time_col TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE relation_punish_notice (

    id INTEGER PRIMARY KEY AUTOINCREMENT,

    type TEXT NOT NULL,

    punish_id INTEGER NOT NULL,

    notice_id INTEGER NOT NULL,

    created_at TIMESTAMP DEFAULT (datetime('now', 'localtime')),

    UNIQUE (punish_id, notice_id, type)

);
CREATE TABLE "tpex_afterTrading_tradingIndex" (

	"id"	INTEGER,

	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP, 日期 TEXT, 日期_ts INTEGER, 成交張數 INTEGER, 金額_仟元 INTEGER, 筆數 INTEGER, 櫃買指數 INTEGER, 漲_跌 REAL,

	PRIMARY KEY("id" AUTOINCREMENT)

);
CREATE TABLE tpex_bulletin_attention (

    id INTEGER PRIMARY KEY AUTOINCREMENT,

    證券代號 TEXT,

    證券名稱 TEXT,

    累計 INTEGER,

    注意交易資訊 TEXT,

    公告日期 TEXT,

    收盤價 REAL,

    本益比 REAL,

    link TEXT,

    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 公告日期_ts INTEGER, law_src TEXT,

	UNIQUE (證券代號, 公告日期)  -- 假設編號+證券代號+公告日期唯一

);


