	"證券代號"	TEXT,

	"證券名稱"	TEXT,

	"累計"	INTEGER,

	"處置起訖時間"	TEXT,	

	"處置原因" TEXT,

	"處置內容"	TEXT,

	"收盤價"	REAL,

	"本益比"	REAL,

	"memo" TEXT,

	"created_at"	TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

