CREATE TABLE "tpex_insti_summary" (

	"id"	INTEGER,

	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP, date TEXT, date_ts INTEGER, 單位名稱 TEXT, 買進金額_元 INTEGER, 賣出金額_元 INTEGER, 買賣超_元 INTEGER,

	PRIMARY KEY("id" AUTOINCREMENT)

);
CREATE TABLE "tpex_margin_balance" (

	"id"	INTEGER,

	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP,

	PRIMARY KEY("id" AUTOINCREMENT)

);
CREATE TABLE "twse_afterTradingFmtqik" (

	"id"	INTEGER,

	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP,

	PRIMARY KEY("id" AUTOINCREMENT)

);
CREATE TABLE twse_announcement_notice (

    id INTEGER PRIMARY KEY AUTOINCREMENT,

    證券代號 TEXT,

    證券名稱 TEXT,

    累計次數 INTEGER,

    注意交易資訊 TEXT,

    日期 TEXT,

    收盤價 REAL,

    本益比 REAL,

    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 日期_ts INTEGER, law_src TEXT,

    UNIQUE (證券代號, 日期)  -- 保證同一證券在同一天只有一筆

);
CREATE TABLE "twse_announcement_punish" (

	"id"	INTEGER,

	"公布日期"	TEXT,

	"證券代號"	TEXT,

	"證券名稱"	TEXT,

	"累計"	INTEGER,

	"處置條件"	TEXT,	

	"處置起迄時間" TEXT,

	"處置措施"	TEXT,

	"處置內容"	TEXT,

	"備註"	TEXT,

	"created_at"	TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

	"公布日期_ts"	INTEGER, law_src TEXT, last_notice INTEGER, notice_cnt INTEGER,

	PRIMARY KEY("id" AUTOINCREMENT),

	UNIQUE("證券代號","公布日期")

);

２處置期間：自民國一百十四年九月二十三日起至一百十四年十月八日﹝十個營業日，如遇：ａ有價證券最後交易日在處置期間，僅處置至最後交易日，ｂ有價證券停止買賣、全日暫停交易則順延執行，ｃ開休市日變動則調整處置迄日〕。
３處置措施：
ａ以人工管制之撮合終端機執行撮合作業（約每五分鐘撮合一次）。
ｂ投資人每日委託買賣該有價證券數量單筆達十交易單位或多筆累積達三十交易單位以上時，應就其當日已委託之買賣，向該投資人收取全部之買進價金或賣出證券。
ｃ信用交易部分，應收足融資自備款或融券保證金。有關信用交易了結部分，則依相關規定辦理。','提供處置有價證券連結資訊<br>
