CREATE TABLE "twse_fund_bfi82u" (

	"id"	INTEGER,

	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP,

	PRIMARY KEY("id" AUTOINCREMENT)

);
CREATE TABLE "twse_marginTrading_miMargn" (
	"id"	INTEGER,
	"日期"	TEXT,
	"項目"	TEXT,
	"買進"	INTEGER,
	"賣出"	INTEGER,
	"現金_券_償還"	INTEGER,
	"前日餘額"	INTEGER,
	"今日餘額"	INTEGER,
	"created_at"	TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT),
	UNIQUE("日期","項目")
);
CREATE TABLE "twse_taiex_mi5minsHist" (

	"id"	INTEGER,

	"created_at"	DATETIME DEFAULT CURRENT_TIMESTAMP,

	PRIMARY KEY("id" AUTOINCREMENT)

);
CREATE VIEW v_data_source AS

SELECT

    DS.name,

	DS.storage_table,

	DS.api_method,

    DS.src_link || DS.api_path || '?' || DS.api_params AS api_sample,

	DS.src_link || DS.web_path AS web_page,

	DS.api_res_sample,

	DS.memo

FROM

    data_source AS DS;
CREATE UNIQUE INDEX idx_data_source_name ON data_source (name);
CREATE VIEW v_attention_notice AS
SELECT
	'twse' AS "來源",
	strftime('%Y/%m/%d', datetime(日期_ts, 'unixepoch'))  AS "公告日期",
    "證券代號",
    "證券名稱",

	"law_src",
    "累計次數" AS "累計",        
    "收盤價",
    "本益比",
	"注意交易資訊"
FROM twse_announcement_notice

UNION ALL

SELECT
	'tpex' AS "來源",
	strftime('%Y/%m/%d', datetime(公告日期_ts, 'unixepoch'))  AS "公告日期",
    "證券代號",
    "證券名稱",

	"law_src",
    "累計",       
    "收盤價",
    "本益比",
	"注意交易資訊"
FROM tpex_bulletin_attention;
DELETE FROM "sqlite_sequence";
COMMIT;
